<?php
namespace App\Http\Controllers\Api; use App\Http\Requests\Api\ContractRequest; use App\Models\Contract; use App\Traits\ApiResponseTrait; use Illuminate\Http\Request;
class ContractController {use ApiResponseTrait; public function index(Request $r){return $this->success(Contract::with('employee')->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->status,fn($q,$v)=>$q->where('status',$v))->latest()->paginate(15));} public function store(ContractRequest $r){return $this->success(Contract::create($r->validated()),'Contract created',201);} public function show(Contract $contract){return $this->success($contract->load('employee'));} public function update(ContractRequest $r,Contract $contract){$contract->update($r->validated());return $this->success($contract->fresh());} public function destroy(Contract $contract){$contract->update(['status'=>'terminated','termination_date'=>now()]);return $this->success($contract,'Contract terminated');} public function employee(int $employee){return $this->success(Contract::where('employee_id',$employee)->latest()->get());} public function expiring(Request $r){$days=(int)$r->get('days',30);return $this->success(Contract::where('status','active')->whereBetween('end_date',[now(),now()->addDays($days)])->with('employee')->get());}}
